begin;create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table publication_fixture(source uuid,mark uuid,result uuid,evidence uuid);grant select,insert,update on publication_fixture to cuevo_api;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','bf100000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Publication course','School native source','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values('10000000-0000-4000-8000-000000000001','bf110000-0000-4000-8000-000000000001','bf100000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Private source result','School task',10,'61000000-0000-4000-8000-000000000001',2);
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
insert into publication_fixture(source)select internal.create_learning_submission('bf110000-0000-4000-8000-000000000001','Immutable school source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);update publication_fixture set mark=internal.mark_submission(source,0,'Native zero',2,0,true);update publication_fixture set result=internal.release_marking(mark,1,false);update publication_fixture set evidence=(select evidence_id from app.result_revisions where id=result);
select is(internal.read_result_publication((select result from publication_fixture))->>'publicationRevision','0','Release-time approval is revision zero compatibility');
select lives_ok($$select internal.publish_result_parent((select result from publication_fixture),'{"parentVisible":true,"expectedPublicationRevision":0,"expectedResultRevision":1,"reason":"Reviewed independent parent sharing","confirmPublication":true}','publication-share',repeat('a',64),'publication')$$,'Originally private native result can be shared independently');
select lives_ok($$select internal.publish_result_parent((select result from publication_fixture),'{"parentVisible":true,"expectedPublicationRevision":0,"expectedResultRevision":1,"reason":"Reviewed independent parent sharing","confirmPublication":true}','publication-share',repeat('a',64),'publication')$$,'Original-key sharing replay is exact');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select count(*)from app.result_revisions where id=(select result from publication_fixture)),1::bigint,'Current approved parent reads originally private result');
select is((select count(*)from app.academic_evidence where id=(select evidence from publication_fixture)),1::bigint,'Evidence shares the same current publication');
select lives_ok($$select internal.read_academic_revision_page((select result from publication_fixture),25,null)$$,'Current publication permits exact native history');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select lives_ok($$select internal.publish_result_parent((select result from publication_fixture),'{"parentVisible":false,"expectedPublicationRevision":1,"expectedResultRevision":1,"reason":"Reviewed parent sharing revocation","confirmPublication":true}','publication-revoke',repeat('b',64),'publication')$$,'Revocation is an independent immutable access revision');
select throws_ok($$select internal.publish_result_parent((select result from publication_fixture),'{"parentVisible":true,"expectedPublicationRevision":1,"expectedResultRevision":1,"reason":"Stale publication context","confirmPublication":true}','publication-stale',repeat('c',64),'publication')$$,'22023',null,'Stale publication cannot reshare');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is((select count(*)from app.result_revisions where id=(select result from publication_fixture)),0::bigint,'Revoked parent cannot read native result');
select is((select count(*)from app.academic_evidence where id=(select evidence from publication_fixture)),0::bigint,'Revoked parent cannot read evidence');
select throws_ok($$select internal.read_academic_revision_page((select result from publication_fixture),25,null)$$,'42501',null,'Revoked parent cannot read exact native history');
reset role;
select is((select count(*)from app.result_revisions where assessment_id='bf110000-0000-4000-8000-000000000001'),1::bigint,'Sharing changes no grade revisions');
select is((select parent_visible from app.result_revisions where id=(select result from publication_fixture)),false,'Original release approval remains immutable fact');
select throws_ok($$update app.result_publication_revisions set reason='Overwrite'where result_id=(select result from publication_fixture)$$,'55000',null,'Publication history is immutable');
select ok(not has_table_privilege('cuevo_api','app.result_publication_revisions','SELECT')and not has_function_privilege('authenticated','internal.publish_result_parent(uuid,jsonb,text,text,text)','EXECUTE'),'No raw browser/API publication grants');
select*from finish();rollback;
